import functools


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        # Include keyword arguments in the key so that `f(a, b, units="mi")`
        # is not treated as identical to `f(a, b)`; keyword order must not
        # matter, so use a sorted mapping proxy.
        key = (args, tuple(sorted(kwargs.items())))
        try:
            if key in cache:
                stats["hits"] += 1
                return cache[key]
        except TypeError:
            # Unhashable arguments: run the function, but don't cache.
            return fn(*args, **kwargs)
        stats["misses"] += 1
        result = fn(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
